//! The About screen (REQ-342): the recorder's own bundled components and licences.

use videolore::notices::{Component, components};

/// The recorder's notices.
pub const THIRD_PARTY: &str = include_str!("../../packaging/notices/third-party-screen-spy.txt");
/// Its Rust crates and their licences, generated by `scripts/notices.sh`.
pub const RUST_CRATES: &str = include_str!("../../packaging/notices/rust-crates-screen-spy.txt");

/// The components of the editor's list that the recorder bundles.
const BUNDLED: [&str; 5] = ["FFmpeg", "x264", "x265", "libass", "Phosphor Icons"];

/// The recorder's bundled components.
pub fn bundled() -> Vec<Component> {
    let mut all = components(None);
    all.retain(|c| BUNDLED.contains(&c.name));
    all
}

/// The full About text.
pub fn text() -> String {
    let mut out = format!(
        "videolore screen spy {} — GPL-3.0-only — Copyright (C) Andrea Lorenzani\n\n\
         Bundled components\n",
        env!("CARGO_PKG_VERSION")
    );
    for c in bundled() {
        out.push_str(&format!(
            "  {}  {}  [{}]  {}\n",
            c.name, c.version, c.licence, c.source
        ));
    }
    out.push('\n');
    out.push_str(THIRD_PARTY);
    out.push('\n');
    out.push_str(RUST_CRATES);
    out
}
